-- D18 L3: 在 A001 内分别统计两类数据：燃气管线按 pressure_level 分组汇总裁剪后长度，水管按 pipe_type 分组汇总裁剪后长度，单位均为米。每类按总长度降序、同长按分组名称升序，输出全部分组，保留零长度非空接触记录。
-- 独立只读基准；EPSG:3857、quad_segs=8；不调用工具或执行器。
-- 燃气和水管是独立分支；都先裁剪到 A001；边界线段计入，空几何剔除；不做跨管线空间 union。
WITH a AS (SELECT geom FROM gis_lab.construction_areas WHERE code='A001'), gas_cut AS (SELECT g.pressure_level AS label,ST_Intersection(g.geom,a.geom) AS geom FROM gis_lab.gas_pipelines g CROSS JOIN a WHERE ST_Intersects(g.geom,a.geom)), water_cut AS (SELECT w.pipe_type AS label,ST_Intersection(w.geom,a.geom) AS geom FROM gis_lab.water_pipelines w CROSS JOIN a WHERE ST_Intersects(w.geom,a.geom)), gas_grouped AS (SELECT label,sum(ST_Length(geom)) AS value,count(*) AS n FROM gas_cut WHERE NOT ST_IsEmpty(geom) GROUP BY label), water_grouped AS (SELECT label,sum(ST_Length(geom)) AS value,count(*) AS n FROM water_cut WHERE NOT ST_IsEmpty(geom) GROUP BY label) SELECT jsonb_build_object('gas_groups',COALESCE((SELECT jsonb_agg(jsonb_build_object('group',jsonb_build_object('pressure_level',label),'value',value,'feature_count',n) ORDER BY value DESC,label COLLATE "C") FROM gas_grouped),'[]'::jsonb),'water_groups',COALESCE((SELECT jsonb_agg(jsonb_build_object('group',jsonb_build_object('pipe_type',label),'value',value,'feature_count',n) ORDER BY value DESC,label COLLATE "C") FROM water_grouped),'[]'::jsonb),'unit','meter') AS answer;
